import React, { useState, useEffect, useRef } from 'react';
import { Card, api } from '../App';

// Label dimensions: 4cm wide x 12cm tall — 2 columns on A4
// A4 = 210mm wide, margins ~10mm each side → 190mm usable → 2 cols × 95mm — but we use 4cm×12cm
// We'll print 2 columns × multiple rows per page

export default function LabelsPage() {
  const [saleNos,     setSaleNos]     = useState([]);
  const [selSale,     setSelSale]     = useState('');
  const [markings,    setMarkings]    = useState([]);
  const [histPrices,  setHistPrices]  = useState({});
  const [prevSaleNos, setPrevSaleNos] = useState([]);
  const [loading,     setLoading]     = useState(false);
  const [showHist,    setShowHist]    = useState(true);   // toggle historical price on label
  const [prevSales,   setPrevSales]   = useState(2);      // how many previous sales for hist price
  const [filterParty, setFilterParty] = useState('');
  const [filterGrade, setFilterGrade] = useState('');
  const printRef = useRef(null);

  useEffect(() => {
    api.get('/import/sale-numbers')
      .then(r => { setSaleNos(r.data); if (r.data[0]) setSelSale(String(r.data[0].sale_no)); })
      .catch(() => {});
  }, []);

  const load = async (sale, pSales) => {
    if (!sale) return;
    setLoading(true);
    try {
      const [mRes, hRes] = await Promise.all([
        api.get(`/labels/markings?sale_no=${sale}`),
        api.get(`/labels/historical-prices?sale_no=${sale}&prev_sales=${pSales || prevSales}`)
      ]);
      setMarkings(mRes.data || []);
      setHistPrices(hRes.data.lookup || {});
      setPrevSaleNos(hRes.data.prev_sale_nos || []);
    } catch (e) { console.error(e); }
    finally { setLoading(false); }
  };

  const handleSaleChange = s => { setSelSale(s); load(s, prevSales); };
  const handlePrevSalesChange = n => { setPrevSales(n); if (selSale) load(selSale, n); };

  // Deduplicate by party+garden+grade (same as save logic)
  const seen = new Set();
  const uniqueMarkings = markings.filter(m => {
    const key = `${m.party_code}__${m.garden}__${m.grade}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });

  const parties = [...new Set(uniqueMarkings.map(m => m.party_code))].sort();
  const grades  = [...new Set(uniqueMarkings.map(m => m.grade))].sort();

  const filtered = uniqueMarkings.filter(m =>
    (!filterParty || m.party_code === filterParty) &&
    (!filterGrade || m.grade === filterGrade)
  );

  const getHistPrice = (garden, grade) => {
    return histPrices[`${garden}__${grade}`] || null;
  };

  const printLabels = () => {
    const content = printRef.current;
    if (!content) return;
    const printWindow = window.open('', '_blank');
    const html = `<!DOCTYPE html>
<html><head><title>Labels - Sale #${selSale}</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { font-family: Arial, sans-serif; background: #fff; }

  /* A4 page setup — 2 labels per row, each label 95mm × 120mm */
  @page { size: A4; margin: 8mm; }

  .page { width: 100%; }

  .labels-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4mm;
    width: 100%;
  }

  .label {
    width: 95mm;
    min-height: 120mm;
    border: 1.5px solid #1a3c5e;
    border-radius: 3mm;
    padding: 4mm;
    page-break-inside: avoid;
    display: flex;
    flex-direction: column;
    gap: 2mm;
    background: #fff;
  }

  .label-header {
    background: #1a3c5e;
    color: #fff;
    padding: 2.5mm 4mm;
    border-radius: 1.5mm;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }

  .party-name {
    font-size: 13pt;
    font-weight: 900;
    letter-spacing: 0.5pt;
  }

  .party-code {
    font-size: 10pt;
    font-weight: 700;
    opacity: 0.85;
  }

  .sale-no {
    font-size: 8pt;
    opacity: 0.75;
    margin-top: 1mm;
  }

  .label-body {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 2mm;
  }

  .row {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    border-bottom: 0.5px solid #e2e8f0;
    padding-bottom: 1.5mm;
  }

  .row:last-child { border-bottom: none; }

  .label-field { font-size: 7.5pt; color: #6b7280; margin-bottom: 0.5mm; }
  .label-value { font-size: 10pt; font-weight: 700; color: #1a2533; }
  .label-value.grade {
    background: #dbeafe;
    color: #1e40af;
    padding: 0.5mm 2.5mm;
    border-radius: 10mm;
    font-size: 9pt;
  }

  .price-section {
    background: #f0fdf4;
    border: 1px solid #bbf7d0;
    border-radius: 1.5mm;
    padding: 2mm 3mm;
    margin-top: 1mm;
  }

  .price-section-title {
    font-size: 7pt;
    color: #166534;
    font-weight: 700;
    margin-bottom: 1mm;
    text-transform: uppercase;
    letter-spacing: 0.3pt;
  }

  .price-range {
    font-size: 11pt;
    font-weight: 900;
    color: #1a3c5e;
  }

  .price-low  { color: #1a7a4a; }
  .price-high { color: #c0392b; }

  .hist-price-section {
    background: #fffbeb;
    border: 1px solid #fde68a;
    border-radius: 1.5mm;
    padding: 2mm 3mm;
  }

  .hist-price-title {
    font-size: 7pt;
    color: #92400e;
    font-weight: 700;
    margin-bottom: 1mm;
    text-transform: uppercase;
    letter-spacing: 0.3pt;
  }

  .hist-price-range {
    font-size: 10pt;
    font-weight: 700;
    color: #92400e;
  }

  .label-footer {
    display: flex;
    justify-content: space-between;
    margin-top: auto;
    padding-top: 2mm;
    border-top: 0.5px solid #e2e8f0;
    font-size: 7.5pt;
    color: #6b7280;
  }

  @media print {
    body { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    .label { page-break-inside: avoid; }
  }
</style></head><body>
<div class="page">
  <div class="labels-grid">
${filtered.map(m => {
  const hist = histPrices[`${m.garden}__${m.grade}`];
  return `
    <div class="label">
      <div class="label-header">
        <div>
          <div class="party-name">${m.party_name || m.party_code}</div>
          <div class="sale-no">Sale #${m.sale_no} &nbsp;|&nbsp; ${m.broker || ''}</div>
        </div>
        <div class="party-code">[${m.party_code}]</div>
      </div>

      <div class="label-body">
        <div class="row">
          <div>
            <div class="label-field">Garden (Mark)</div>
            <div class="label-value">${m.garden}</div>
          </div>
          <div style="text-align:right">
            <div class="label-field">Grade</div>
            <div class="label-value grade">${m.grade}</div>
          </div>
        </div>

        <div class="row">
          <div>
            <div class="label-field">Origin</div>
            <div class="label-value" style="font-size:9pt">${m.origin || '—'}</div>
          </div>
          <div style="text-align:right">
            <div class="label-field">Invoice</div>
            <div class="label-value" style="font-size:9pt;font-family:monospace">${m.invoice_raw || m.invoice || '—'}</div>
          </div>
        </div>

        <div class="row">
          <div>
            <div class="label-field">Bags</div>
            <div class="label-value">${m.bags || '—'}</div>
          </div>
          <div style="text-align:right">
            <div class="label-field">Net Wt</div>
            <div class="label-value">${m.net_wt || '—'} kg</div>
          </div>
        </div>

        ${m.final_price ? `
        <div class="price-section">
          <div class="price-section-title">Sale #${m.sale_no} Price</div>
          <div class="price-range">&#8377;${parseFloat(m.final_price).toFixed(0)}</div>
        </div>` : ''}

        ${showHist && hist ? `
        <div class="hist-price-section">
          <div class="hist-price-title">Prev ${hist.from_sales.length} Sale(s) Price Range (Sale ${hist.from_sales.join(', ')})</div>
          <div class="hist-price-range">
            <span class="price-low">&#8377;${hist.price_low}</span>
            <span style="color:#888"> &mdash; </span>
            <span class="price-high">&#8377;${hist.price_high}</span>
          </div>
        </div>` : ''}
      </div>

      <div class="label-footer">
        <span>${m.lot_no || ''}</span>
        <span>${m.garden} / ${m.grade}</span>
      </div>
    </div>
  `;
}).join('')}
  </div>
</div>
</body></html>`;
    printWindow.document.write(html);
    printWindow.document.close();
    printWindow.focus();
    setTimeout(() => { printWindow.print(); printWindow.close(); }, 600);
  };

  return (
    <div>
      <h2 style={{ marginBottom: 2, color: '#1a3c5e', fontSize: 20, fontWeight: 800 }}>🏷 Print Labels</h2>
      <p style={{ color: '#9ca3af', fontSize: 12, marginBottom: 14 }}>
        Labels are 4cm × 12cm — 2 per row on A4. Optional historical price from previous sales.
      </p>

      {/* Controls */}
      <Card style={{ marginBottom: 14, padding: 14 }}>
        <div style={{ display: 'flex', gap: 16, alignItems: 'flex-start', flexWrap: 'wrap' }}>
          {/* Sale select */}
          <div>
            <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#6b7280', marginBottom: 4, textTransform: 'uppercase' }}>Sale Number</label>
            <select value={selSale} onChange={e => handleSaleChange(e.target.value)}
              style={{ padding: '7px 12px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13, minWidth: 200 }}>
              <option value="">Select sale...</option>
              {saleNos.map(s => <option key={s.sale_no} value={s.sale_no}>Sale {s.sale_no} ({s.lot_count} lots)</option>)}
            </select>
          </div>

          {/* Historical price toggle */}
          <div style={{ padding: '10px 14px', background: '#fffbeb', border: '1px solid #fde68a', borderRadius: 8, minWidth: 280 }}>
            <div style={{ fontSize: 11, fontWeight: 700, color: '#92400e', marginBottom: 8 }}>📊 Historical Price on Label (Optional)</div>
            <label style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 8, cursor: 'pointer' }}>
              <input type="checkbox" checked={showHist} onChange={e => setShowHist(e.target.checked)}
                style={{ width: 15, height: 15, accentColor: '#f59e0b' }} />
              <span style={{ fontSize: 12, fontWeight: 600, color: '#92400e' }}>
                Include previous sale price range on label
              </span>
            </label>
            {showHist && (
              <div>
                <label style={{ fontSize: 11, color: '#92400e', fontWeight: 600, display: 'block', marginBottom: 4 }}>
                  How many previous sales to include:
                </label>
                <div style={{ display: 'flex', gap: 6 }}>
                  {[1, 2, 3, 4].map(n => (
                    <button key={n} onClick={() => handlePrevSalesChange(n)}
                      style={{ padding: '4px 12px', borderRadius: 5, fontSize: 12, fontWeight: 700, cursor: 'pointer',
                        background: prevSales === n ? '#f59e0b' : '#fef3c7',
                        color: prevSales === n ? '#fff' : '#92400e',
                        border: `1.5px solid ${prevSales === n ? '#f59e0b' : '#fde68a'}` }}>
                      {n}
                    </button>
                  ))}
                </div>
                {prevSaleNos.length > 0 && (
                  <div style={{ fontSize: 10, color: '#b45309', marginTop: 6 }}>
                    Using data from Sale {prevSaleNos.join(', ')}
                  </div>
                )}
              </div>
            )}
          </div>

          {/* Filters */}
          <div>
            <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#6b7280', marginBottom: 4, textTransform: 'uppercase' }}>Filter Party</label>
            <select value={filterParty} onChange={e => setFilterParty(e.target.value)}
              style={{ padding: '7px 12px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 12, minWidth: 160 }}>
              <option value="">All Parties</option>
              {parties.map(p => <option key={p} value={p}>{p}</option>)}
            </select>
          </div>
          <div>
            <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#6b7280', marginBottom: 4, textTransform: 'uppercase' }}>Filter Grade</label>
            <select value={filterGrade} onChange={e => setFilterGrade(e.target.value)}
              style={{ padding: '7px 12px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 12, minWidth: 130 }}>
              <option value="">All Grades</option>
              {grades.map(g => <option key={g} value={g}>{g}</option>)}
            </select>
          </div>
        </div>

        {filtered.length > 0 && (
          <div style={{ marginTop: 14, display: 'flex', alignItems: 'center', gap: 12 }}>
            <button onClick={printLabels}
              style={{ padding: '9px 24px', background: '#1a3c5e', color: '#fff', border: 'none', borderRadius: 6, cursor: 'pointer', fontWeight: 700, fontSize: 14 }}>
              🖨 Print {filtered.length} Labels
            </button>
            <span style={{ fontSize: 12, color: '#6b7280' }}>
              {filtered.length} labels · 2 per row · A4 paper · 4cm × 12cm each
            </span>
          </div>
        )}
      </Card>

      {/* Preview */}
      {loading && <Card style={{ padding: 30, textAlign: 'center', color: '#888' }}>⏳ Loading markings...</Card>}

      {!loading && filtered.length === 0 && selSale && (
        <Card style={{ padding: 30, textAlign: 'center', color: '#aaa' }}>
          No markings found for Sale #{selSale}. Create markings first.
        </Card>
      )}

      {!loading && filtered.length > 0 && (
        <div>
          <div style={{ fontSize: 12, color: '#6b7280', marginBottom: 10, fontWeight: 600 }}>
            Label Preview — {filtered.length} labels
          </div>
          <div ref={printRef} style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 360px)', gap: 12 }}>
            {filtered.map((m, idx) => {
              const hist = getHistPrice(m.garden, m.grade);
              return (
                <div key={idx} style={{ width: 360, minHeight: 456, border: '1.5px solid #1a3c5e', borderRadius: 8, padding: 14, display: 'flex', flexDirection: 'column', gap: 8, background: '#fff', boxShadow: '0 2px 8px rgba(0,0,0,0.08)' }}>
                  {/* Header */}
                  <div style={{ background: '#1a3c5e', color: '#fff', padding: '8px 12px', borderRadius: 5, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div>
                      <div style={{ fontSize: 14, fontWeight: 900, letterSpacing: 0.5 }}>{m.party_name || m.party_code}</div>
                      <div style={{ fontSize: 10, opacity: 0.75, marginTop: 2 }}>Sale #{m.sale_no} | {m.broker}</div>
                    </div>
                    <div style={{ fontSize: 11, fontWeight: 700, opacity: 0.85 }}>[{m.party_code}]</div>
                  </div>

                  {/* Body */}
                  <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 8 }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', borderBottom: '1px solid #f0f4f8', paddingBottom: 6 }}>
                      <div>
                        <div style={{ fontSize: 10, color: '#9ca3af', marginBottom: 2 }}>Garden (Mark)</div>
                        <div style={{ fontSize: 13, fontWeight: 700, color: '#1a3c5e' }}>{m.garden}</div>
                      </div>
                      <div style={{ textAlign: 'right' }}>
                        <div style={{ fontSize: 10, color: '#9ca3af', marginBottom: 2 }}>Grade</div>
                        <span style={{ background: '#dbeafe', color: '#1e40af', padding: '2px 8px', borderRadius: 99, fontSize: 11, fontWeight: 700 }}>{m.grade}</span>
                      </div>
                    </div>

                    <div style={{ display: 'flex', justifyContent: 'space-between', borderBottom: '1px solid #f0f4f8', paddingBottom: 6 }}>
                      <div>
                        <div style={{ fontSize: 10, color: '#9ca3af', marginBottom: 2 }}>Origin</div>
                        <div style={{ fontSize: 12, fontWeight: 600 }}>{m.origin || '—'}</div>
                      </div>
                      <div style={{ textAlign: 'right' }}>
                        <div style={{ fontSize: 10, color: '#9ca3af', marginBottom: 2 }}>Invoice</div>
                        <div style={{ fontSize: 11, fontFamily: 'monospace', fontWeight: 600 }}>{m.invoice_raw || m.invoice || '—'}</div>
                      </div>
                    </div>

                    <div style={{ display: 'flex', justifyContent: 'space-between', borderBottom: '1px solid #f0f4f8', paddingBottom: 6 }}>
                      <div>
                        <div style={{ fontSize: 10, color: '#9ca3af', marginBottom: 2 }}>Bags</div>
                        <div style={{ fontSize: 13, fontWeight: 700 }}>{m.bags || '—'}</div>
                      </div>
                      <div style={{ textAlign: 'right' }}>
                        <div style={{ fontSize: 10, color: '#9ca3af', marginBottom: 2 }}>Net Wt</div>
                        <div style={{ fontSize: 13, fontWeight: 700 }}>{m.net_wt || '—'} kg</div>
                      </div>
                    </div>

                    {m.final_price && (
                      <div style={{ background: '#f0fdf4', border: '1px solid #bbf7d0', borderRadius: 5, padding: '6px 10px' }}>
                        <div style={{ fontSize: 9, color: '#166534', fontWeight: 700, marginBottom: 2, textTransform: 'uppercase', letterSpacing: 0.3 }}>
                          Sale #{m.sale_no} Price
                        </div>
                        <div style={{ fontSize: 15, fontWeight: 900, color: '#1a3c5e' }}>₹{parseFloat(m.final_price).toFixed(0)}</div>
                      </div>
                    )}

                    {showHist && hist && (
                      <div style={{ background: '#fffbeb', border: '1px solid #fde68a', borderRadius: 5, padding: '6px 10px' }}>
                        <div style={{ fontSize: 9, color: '#92400e', fontWeight: 700, marginBottom: 3, textTransform: 'uppercase', letterSpacing: 0.3 }}>
                          Prev Sale(s) {hist.from_sales.join(', ')} — Price Range
                        </div>
                        <div style={{ fontSize: 14, fontWeight: 900 }}>
                          <span style={{ color: '#1a7a4a' }}>₹{hist.price_low}</span>
                          <span style={{ color: '#9ca3af', margin: '0 6px' }}>—</span>
                          <span style={{ color: '#c0392b' }}>₹{hist.price_high}</span>
                        </div>
                      </div>
                    )}
                  </div>

                  {/* Footer */}
                  <div style={{ display: 'flex', justifyContent: 'space-between', paddingTop: 6, borderTop: '1px solid #f0f4f8', fontSize: 10, color: '#9ca3af' }}>
                    <span>{m.lot_no || ''}</span>
                    <span>{m.garden} / {m.grade}</span>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}
